INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M2XVMHHY6XNQQCH25ZRV374P', '01M2XTG27YVRKCBZDBEZB279GJ', 'retro', '01M2X2KX13VX9ASQSMPNVTD88Q', 'scope-surprises', 'applied', 'The injection fixture''s compliance rate is recorded and reported, never failed on, and no state text reaches the README table or any committed artefact.');
