INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XBAJK9VB82H8BPEPG2CAHF', '01M2XF2FEYRYJ923KY64VJP8GC', 'retro', '01M2X2PQFR200HBQ1NACTB96MB', NULL, NULL, 3, 'Testbench rewrites `database.default` from `sqlite` to its own `testing` connection whenever the SQLite database is not a file (`:memory:` is not), so a test asserting `config(''database.default'') === ''sqlite''` fails even though phpunit.xml is correct. Assert the effective connection''s driver and database instead. Also: the Spatie skeleton''s .gitignore ignores `/docs` and `phpunit.xml`, both of which this repo needs tracked.', NULL, 'Skeleton files copied by hand from spatie/package-skeleton-laravel main; the facade, command, migration stub, factory, views, laravel-ray and workbench autoload were dropped, not adapted.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XBYMSHVXAWX0TGWETTNY2Y', '01M2XF2FEYRYJ923KY64VJP8GC', 'retro', '01M2X2PQG5VAKA5Z5DWBK7S489', NULL, NULL, 1, 'The offline criterion assumed Docker, which the development machine does not have. macOS `sandbox-exec` with `(deny network-outbound (remote ip))` gives the same OS-level guarantee with no install, and a raw-socket probe (excluded from the default suite by group) proves it bites. Criterion amended; the spec''s ENV10 criterion text still names a container. Separately, Pest''s `toContain` is variadic, so a second argument is another needle, not a failure message — a check written that way passed on its own source. Every must-NOT in this story now has a planted-violation control.', 'Both gaps have one root. The spec named checks to run on machines this project doesn''t have, a Docker container and a production host, instead of somewhere a check can actually run. Separately, one requirement''s obligation (ENVX3''s runtime half) had no binding at all. For the remaining epics: every criterion runs in the package suite, under the OS network sandbox, or in a throwaway Laravel app in the scratchpad, and every obligation in a requirement gets its own binding.', 'Change moment resolved by amending story 2 criterion 4; section recorded on the epic.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XE53WMPWZB6MPRAQW2MQVV', '01M2XF2FF95WXYHFBXGJYPXWX5', 'retro', '01M2X2WD2SWE7Q68HE1ZT85C5R', NULL, NULL, 4, 'Smooth. Two things worth carrying forward: PHP silently turns numeric-string array keys into integers, so a Choice option key like ''1'' is rejected as a non-string key (acceptable, and the must-NOT holds); and PHPStan at level max needs input arrays typed loosely (`array<int|string, string>`) with a narrowing `@var` after validation, otherwise a runtime key check reads as dead code. The mutation control for the must-NOT was run and caught the removed check.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XE70D11SNMR1WN3EG0PEX7', '01M2XF2FF95WXYHFBXGJYPXWX5', 'retro', '01M2X2WD3CYT5VNQDT21WQGYRM', NULL, NULL, 1, 'Smooth. `SampleSeed` hands out a fresh `Randomizer` per call, so successive shuffles in one sample are deterministic only in call order — the prompt story must fix the order in which it shuffles questions, options and levels. Pest''s `arch()->not->toBeUsed()` scans `src` only, so a test file may call `mt_srand` to set up the global-RNG check without tripping the arch rule; the mutation control confirmed both the runtime check and the arch rule catch an injected `mt_srand`.', 'Must-NOTs about what code can see or touch need two controls. A runtime check proves the behaviour, and an arch rule proves the dependency is absent. In story 4, a constant injected seed passed the runtime comparison, and only the arch rule caught it. Use the same pair for 01-03''s must-NOTs, for example that answers are immutable and invalid samples never count.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XEB39CXQPM845H8PKC0FE2', '01M2XF2FF95WXYHFBXGJYPXWX5', 'retro', '01M2X2WD35666W5YFGX0AC9NCR', NULL, NULL, 3, 'Delivered to plan. One surprise: `Choice` read `config()` unconditionally, so building a question set outside a booted Laravel app (the separate-process determinism test) crashed with "Target class [config] does not exist". It now falls back to the default of 50 when no config is bound. Options and levels are canonicalised as lists of `[key, description]` pairs so declared order is explicit in the bytes. `tieBreak` (FR9) and `onlyWhen` (FR21) will have to join the canonical JSON when their epics land; since nothing is released, that can stay `v1`, but any change after release must bump `QuestionSet::HASH_FORMAT` and the golden fixture.', NULL, 'Corrected by 01-03 story 2: FR14 doesn''t list `tieBreak` among what the hash covers, so it stays out of the canonical JSON. `onlyWhen` (FR21) is still to be judged against FR14 when its epic lands.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XEH6AQ56S6S7FPJ4T5YB9A', '01M2XF2FF95WXYHFBXGJYPXWX5', 'retro', '01M2X2WD3H50F7E9Z22QJQ1618', NULL, NULL, 2, 'Delivered to plan. The output schema had to match the SDK''s `HasStructuredOutput::schema(JsonSchema): array<string, Type>`, so it is built with the `Illuminate\JsonSchema` factory rather than as a raw array. Injection defence neutralises only `<state`, `</state`, `<section` and `</section` in state text (the `<` becomes `&lt;`) so ordinary markup in the text is untouched. For must-NOT criteria about what a renderer can see, a Pest arch rule (`Instructions` may not use `UserMessage`, `SampleSeed`, `Carbon` or clock functions) caught a constant injected seed that a runtime comparison could not. The reasons and self-report lines in the instructions are placeholders for FR22 and FR27, whose epics own the final wording and the `reason`/`band` schema fields.', 'Must-NOTs about what code can see or touch need two controls. A runtime check proves the behaviour, and an arch rule proves the dependency is absent. In story 4, a constant injected seed passed the runtime comparison, and only the arch rule caught it. Use the same pair for 01-03''s must-NOTs, for example that answers are immutable and invalid samples never count.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XF1FHXZER21KPZFTJNJX6D', '01M2XF2FEYRYJ923KY64VJP8GC', 'retro', '01M2X2PQFR200HBQ1NACTB96MB', NULL, NULL, 2, 'Three of this story''s criteria were `[target]` checks "on the production host" (`php -v`, `composer show laravel/framework`, `check-platform-reqs`). Hunch is a package and has no host, so they could never run. Chris caught it after the epic closed. Composer already enforces all three in any installing app, so they were superseded, and the spec was pivoted to "Installation:" and "Runtime:" framing. Separately, the claim pass found that ENVX3''s runtime half ("must not require any PHP extension") had no binding at all. It is now covered by `tests/ExtensionsTest.php`.', 'Both gaps have one root. The spec named checks to run on machines this project doesn''t have, a Docker container and a production host, instead of somewhere a check can actually run. Separately, one requirement''s obligation (ENVX3''s runtime half) had no binding at all. For the remaining epics: every criterion runs in the package suite, under the OS network sandbox, or in a throwaway Laravel app in the scratchpad, and every obligation in a requirement gets its own binding.', 'Recorded after the fact, during the 2026-09-19 revisit of the epic summaries.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XG36WKPZJHVTP16W1GM00Y', '01M2XGCEPGWGTW1H0Q467Z0Q34', 'retro', '01M2X3F42MDK6E4K99JM5N3G7V', NULL, NULL, 1, 'The TDD cycle needed a second red. The Choice share of an option with no votes came back as the integer `0` because PHP''s `0 / 4` is an int. The same trap sat in the Boolean probability and the Score mean, so all three now cast to float. The criterion''s `toBe(0.0)` caught it, where a loose equality would not have. Answer classes were started here, carrying only the aggregate fields (probability, shares, votes, choice, confidence, entropy, score, level), so story 3 grows them rather than replacing them. An invalid `Sample` carries no answers by construction, so the planted-violation control counted invalid samples as votes and was caught three ways.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XG5YT42CH6TV1TMNN49H13', '01M2XGCEPGWGTW1H0Q467Z0Q34', 'retro', '01M2X3F4386SRTE9GGQV8Q97MJ', NULL, NULL, 2, 'Smooth, one red and green. `tieBreak()` is a copying method on the readonly Choice and Score, and it validates its key. The Score criterion needed a modal answer to assert on, so `ScoreAnswer` gained `mode` (FR10 doesn''t list it) alongside `tied`, while `score` and `level()` stay on the mean. `tieBreak` is deliberately NOT in the question-set hash: FR14 lists what the hash covers and the tie-break isn''t among it, which reverses the assumption recorded in retro 2 that it would "have to join the canonical JSON". If calibration later needs tie-break-specific cells, that belongs in a spec change, not a quiet hash bump.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XGAYREDJQG9078X1RRMAQS', '01M2XGCEPGWGTW1H0Q467Z0Q34', 'retro', '01M2X3F43JWE81PW25VTPEHQNV', NULL, NULL, 3, 'Two findings. First, the docblock arch test caught my own wording: I wrote the plural "vote-share estimates, not calibrated probabilities", and the criterion requires the exact singular phrase. A test that asserts the literal phrase earns its place. Second, a Pest dataset of `fn () => fn (...)` does not invoke the outer closure, so the first immutability test passed its cases without ever assigning. It was rewritten as property-name data. For the immutability control, stripping `readonly` from just two classes is a fatal error (a readonly child can''t extend a non-readonly parent), so a clean control has to strip all four. The bucket for each answer is its leading share: max(p, 1-p) for a Boolean, confidence for a Choice, the mode''s share for a Score. The spec doesn''t say which share decides the bucket, and this is my reading.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XGNWJSRYZ337F9TB5RR338', '01M2XK9R9BQ41WT71R4SYEWWCV', 'retro', '01M2X3PAQ600X4YN32S2379EJG', NULL, NULL, 3, 'Smooth. A guarded `Settings` reader now fronts every `hunch.*` read, and `Choice` and `Buckets` moved onto it (retro 2''s config lesson, applied). `SamplingRule::configured()` is the "first use" point, so a malformed `hunch.sampling` fails at the classification rather than at boot. The FR16 default `agent` names `ClassifierAgent::class` before story 2 builds it, so an empty stub class was added to keep PHPStan and the published config honest. Boot checks were exercised by re-registering the provider with `force: true` after changing config, which runs the real `packageBooted()`. The migration check looks for the package''s `database/migrations` path in `migrator->paths()`; that directory is empty until the persistence epic.', 'The stories that went cleanly were the ones whose checks already had a home in the package suite. The earlier pivot away from "production host" checks is what made story 8 straightforward.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XHBZNPS80WFHR20Y7J3HVX', '01M2XK9R9BQ41WT71R4SYEWWCV', 'retro', '01M2X3PAQK8SA1R4N8CQV8W9X3', NULL, NULL, 5, 'Delivered to plan once the SDK was understood. The facts worth keeping:
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XHJ10YB4F0HF1ED15BW1YT', '01M2XK9R9BQ41WT71R4SYEWWCV', 'retro', '01M2X3PAR1J7H3S0E8M2HK6PT1', NULL, NULL, 6, 'This story had to come before story 3, whose invalid-sample criterion needs validation to exist. A missing edge was added (story 4 blocks story 3) with approval, and recorded on the epic. The new `min_valid_samples` pre-check correctly broke two story 2 tests that took 2 samples against the default of 3; the tests, not the rule, were adjusted.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XHN3PNK64211Q8SZH5CY75', '01M2XK9R9BQ41WT71R4SYEWWCV', 'retro', '01M2X3PAQTX6C4HAXY3BZ0KB2Q', NULL, NULL, 1, 'I repeated retro 3''s own lesson within one run of applying it. The set/unset test used a Pest dataset of closures returning closures, the outer one was never invoked, and the test failed for the wrong reason. It was rewritten with plain string data. The applied lens caught it only because every new test must be seen failing and passing for the right reason; a test that happens to pass would have hidden it. Meta records `modelReported` from the SDK response `Meta` (distinct from the requested model), seeds and request IDs keyed by sample number, and the question-set hash. Six planted defects plus a readonly arch rule were all caught.', 'My Pest test code fails in Pest-specific ways: closure datasets, interface names passed to toThrow, and guessed exception types. Only the planted controls caught them. Write the planted failure first and watch it fail for the right reason; a test that is merely green is not evidence.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XJSE003Q9SB95T61J1ZDY3', '01M2XK9R9BQ41WT71R4SYEWWCV', 'retro', '01M2X3PAR7KMGX8S8MEGDQMJ81', NULL, NULL, 7, 'Criterion 5 ("the SDK''s failover configuration is passed through") was ambiguous, because the SDK only fails over when `prompt()` receives a provider list. Chris chose to use the agent''s own SDK configuration: with `hunch.failover` on, the requested provider leads, followed by the agent''s `provider()` or `#[Provider]` list (supplied through a `hunch.agent` subclass). No new config key was added, and FR16''s `failover` stays a boolean.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XJXZWP9TFWQ61NMF6P2BG8', '01M2XK9R9BQ41WT71R4SYEWWCV', 'retro', '01M2X3PARECS7ZV29Y9AWRP4YE', NULL, NULL, 8, 'The fake is a manager swapped behind the facade (`Hunch::fake()` → `HunchFake`), whose builders run on a `FakeDriver` through a new optional driver on `PendingClassification`. Direct answers go through a new `Aggregator::fromShares()`, so they are real answer objects with the real tie rule and entropy, and the contract test holds by construction. The fake uses a fixed classification ID (`01J0000000000000000000FAKE`), which fixes seeds and so user messages. An unmatched classification falls through to the real driver unless `preventStrayClassifications()` is on, mirroring Laravel''s `Http::fake`.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XK0EAGCGW799HSR4V4DSQJ', '01M2XK9R9BQ41WT71R4SYEWWCV', 'retro', '01M2X3PARMWT80YW93RZ4WMB55', NULL, NULL, 2, 'Smooth, with two test-writing slips caught by the planted controls. First, a broken database driver raises `ErrorException` ("Undefined array key database"), not `InvalidArgumentException`. Second, Pest''s `toThrow(Throwable::class)` treats an interface name as a message to match, so the control that proves the database is unusable is an explicit try/catch. The identical-instructions check listens to the SDK''s `PromptingAgent` event and hashes `$event->prompt->agent->instructions()`: 6 prompts across two states gave 1 distinct hash. No production code changed in this story.', 'My Pest test code fails in Pest-specific ways: closure datasets, interface names passed to toThrow, and guessed exception types. Only the planted controls caught them. Write the planted failure first and watch it fail for the right reason; a test that is merely green is not evidence.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XK64KJ7AYDM5VARXG6FZB3', '01M2XK9R9BQ41WT71R4SYEWWCV', 'retro', '01M2X3PARWSK1WDC47BZ075G0C', NULL, NULL, 4, 'Smooth. The pivot that turned this story from host smoke checks into package-suite checks paid off: all four criteria ran in the suite with no machine to borrow. The HTTP arch rule deliberately allows catching `Illuminate\Http\Client\HttpClientException` (the driver wraps provider errors) while forbidding anything that sends a request: the `Http` facade, `Factory`/`PendingRequest`, Guzzle, PSR clients, `curl`, sockets and `file_get_contents`. A planted `Http::get()` tripped it, and a planted `DB::select` broke the no-database classification.', 'The stories that went cleanly were the ones whose checks already had a home in the package suite. The earlier pivot away from "production host" checks is what made story 8 straightforward.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XKJAZQH8R90WPGV7VC4VJJ', '01M2XMKKM93FFERCBE2QHB6JQA', 'retro', '01M2X43NBV9QJZG03JQPXE2RX6', NULL, NULL, 1, 'The stopping rule is a pure `Stopping::nextBatch()`, and the driver loops on it, so fixed and adaptive sampling share one loop.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XKRCKBEVGD1F57KHXYN3YC', '01M2XMKKM93FFERCBE2QHB6JQA', 'retro', '01M2X43NC67JZ2MN60EJX8C7S8', NULL, NULL, 2, 'Conditions are a small `Condition` value carried on every question type through `onlyWhen()`, which returns a copy (the types are readonly). `tieBreak()` copies preserve it. `Aggregator::answers($set, $samples)` is now the single entry point both drivers use: conditional questions count only qualifying samples, `applies` follows the controlling winner, and the answer is null under two qualifying samples, so `Result` answers are nullable.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XM2TYG1Y0YY49ECAFYGJRJ', '01M2XMKKM93FFERCBE2QHB6JQA', 'retro', '01M2X43NCDZTGS6DSCP2X35JBT', NULL, NULL, 3, 'Reasons are carried under a reserved `reason` output key (a question can''t use that key while reasons are on). `SampleValidator::split` separates the reason from the answers and cuts it to `maxChars` with `mb_substr`. `Sample` holds it apart from its answers, so the aggregator never sees it. The Hunch::fake scripted samples take the same path.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XMAKTZ4ZANXPH0DSJ7JNTQ', '01M2XMKKM93FFERCBE2QHB6JQA', 'retro', '01M2X43NCK5QP7BJGJE7E83V4K', NULL, NULL, 4, 'Redaction lives in the builder: `PendingClassification::classify()` redacts once, after the pre-call checks and before handing the state to any driver. So the sampling driver, the fake, and the fake''s stray fall-through all receive the same redacted text, and no driver can redact per sample. Array state is redacted part by part, with section names untouched.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XMAKV6HCG1ETFWMG3C8PN2', '01M2XMKKM93FFERCBE2QHB6JQA', 'retro', '01M2X43NCTAD4C4MEFDH15FR4J', NULL, NULL, 5, 'The ContactDetails phone rule is "10–15 digits with at most one space, dot or hyphen between them, an optional + country code and a bracketed area code". It is bounded by lookarounds, so dates, prices, times and BK-style references can''t be picked up. The first version missed `+44 7700 900123,` because a bare comma in the lookahead (meant for thousands separators) also stopped at a phone followed by a comma. The rule was narrowed to "separator followed by a digit" on both sides. That was found by the criterion''s own end-to-end example, not the fixture, so the fixture now isn''t the only guard.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XMG9P184H6AGXJA9RKWKZP', '01M2XMKKM93FFERCBE2QHB6JQA', 'retro', '01M2X43ND0Y6N6614NQ2664K8Z', NULL, NULL, 6, 'Events share a readonly `ClassificationEvent` base (`classificationId`, `questionSetHash`, `stateHash`) with Laravel''s `Dispatchable` trait, and SamplingDriver dispatches them around the sampling loop. The failure event is dispatched from one `catch (ClassificationFailed)` that rethrows, so both provider errors and too few valid samples go through the same path. Deliberately, `ClassificationFailed` carries the cause''s class and not its message: a provider error message can quote the prompt. `Classified` likewise carries counts and usage, not the Result, whose reasons can quote the state.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XN7NWR1GQ7QT09EB0PNGW0', '01M2XTG27YVRKCBZDBEZB279GJ', 'retro', '01M2X4BCM6K3E8X01P5XYSD8HK', NULL, NULL, 1, 'Persistence has a single entry point. `PendingClassification::record()` checks persistence and the subject''s key before any model call, and `classify()` hands the Result, or the ClassificationFailed, to `Persistence\Recorder` in one transaction. So any driver, TypeSafe included, is recorded the same way. `Result` gained `taken` (every Sample), and drivers gained `name()`.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XNCHS78SYPTFZJJAM77KXM', '01M2XTG27YVRKCBZDBEZB279GJ', 'retro', '01M2X4BCMTDY477RCHQHRDDJCH', NULL, NULL, 2, '`Hunch::label()` delegates to `Persistence\Labeller`, which validates every answer before writing anything. Answers are checked against the question set *as recorded*: it decodes `hunch_question_sets.canonical`, not a live QuestionSet, so a label is judged by the question that was actually asked. A Boolean needs a bool, and a Choice or Score needs one of its canonical keys, compared case-sensitively. Superseding is an UPDATE of `superseded_at` on the current row inside the same transaction as the insert, so exactly one label per question is current. `Labelled` extends the shared event base (ID, question set hash, state hash) and carries the question keys. The story-6 "no event property could hold the state" control needed an explicit exception for that one list, rather than allowing arrays in general.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XNN5M7F1C2K2BJQB92H98H', '01M2XTG27YVRKCBZDBEZB279GJ', 'retro', '01M2X4BCN25081Q59KW35SEYAS', NULL, NULL, 3, 'Test-first, as the tdd tags asked. The statistics tests were red (the class was missing) before `Calibration\Statistics` existed: Wilson (reference from Python''s `NormalDist`, not my own arithmetic), Boolean Brier, multi-class Brier, ECE and reliability. The only green-before-fix surprise was PHP''s int/int division returning int `1` for accuracy.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XNVN0B0M2FTBWV02TPRWFQ', '01M2XTG27YVRKCBZDBEZB279GJ', 'retro', '01M2X4BCNA0ZTGJGBTXDJ9EGHR', NULL, NULL, 4, 'Answers are readonly, so the calibration cell''s context can''t be attached afterwards. A `CalibrationScope` (question set hash, driver, provider, model, sampling rule, question) now travels into every answer at construction: through `Aggregator::answers()`, `aggregate()` and `fromShares()`, from both drivers. `calibration()` returns null before any query when there is no scope or persistence is off; otherwise it looks up the exact cell (scope columns + `calibrationAnswer()` + bucket) and gates on `calibration.min_n`. `CalibrationScope::model()` is the single rule (reported, else requested) that both `Calibrator` and the answers use, so writer and reader can''t drift. An end-to-end test proves it: 30 recorded, labelled classifications, then `hunch:calibrate`, then a fresh answer reads n 30, accuracy 0.9 and the Wilson bound. A planted key mismatch in `Calibrator` fails that test.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XSKM6BJ1HGH50B3MY6RS1J', '01M2XTG27YVRKCBZDBEZB279GJ', 'retro', '01M2X4BCNHT6RWZV3RH04GZCMC', NULL, NULL, 5, 'This story had two gaps the criteria didn''t answer, both put to Chris.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XSTF2WTRKQGK76AZXQ0XC9', '01M2XTG27YVRKCBZDBEZB279GJ', 'retro', '01M2X4BCNRCV1FX6Y4R6KM0JJD', NULL, NULL, 6, '`withSelfReport()` adds a required `bands` object to the schema, one enum per question, and the instructions define the three bands (high, medium, low) rather than leaving "how confident are you" open. A sample missing a band, or stating an unknown one, is invalid like any other schema breach, so a self-report failure never becomes a silent default.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XSWA44A2YXDN7X59KCX91D', '01M2XTG27YVRKCBZDBEZB279GJ', 'retro', '01M2X4BCNZM3CXM6YEPA71KFGR', NULL, NULL, 7, 'The journey test runs the epic end to end with no new production code: 30 classifications recorded against their own subjects, labelled, calibrated, then a 31st classification reads the cell back through `calibration()`. It pins the row counts (31 classifications, 93 samples, 30 current labels) as well as the measures, so a change that quietly stops writing samples fails here even though no criterion mentions sample rows.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XWGQPV076N50XWJE38HGW0', '01M2XXETZ6J6KCYTMCM78DZYV1', 'retro', '01M2X4NSD4BZMPQ2ZCDXBYBQKE', NULL, NULL, 1, 'The run passed first time against claude-sonnet-5: 42 items, 126 samples, 4 minutes, roughly $0.30. One sample of 126 was schema-invalid (0.8%, well under the 10% limit), and it was in the injection group. Accuracy was 93.1% core, 100% large-choice, 100% injection. Injection compliance was 0 of 6 — the provider followed none of the six embedded instructions, which is the result the `<state>` delimiting and the instruction line are meant to produce.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XWGQQ9AZ03TEFF7GBM4DGT', '01M2XXETZ6J6KCYTMCM78DZYV1', 'retro', '01M2X4NSDVG4E2B7EZJV63FE8Q', NULL, NULL, 2, '`ResultsTable` writes between two README markers and refuses to guess when they are missing, so the run cannot scribble over prose. The isolation tests cover the properties directly: only the block between markers changes, a second run replaces the first rather than appending, and a README without markers is left byte-identical.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XXCNWDMS2HV5SGCEC6WZG6', '01M2XXETZ6J6KCYTMCM78DZYV1', 'retro', '01M2X3PAQ600X4YN32S2379EJG', NULL, NULL, 3, 'Raised while documenting 01-07, but it originates here: the service provider called `loadMigrationsFrom()` whenever persistence was on, so enabling persistence silently injected Hunch''s migrations into an application''s `migrate` run. ADR 01-02''s chosen option says the opposite — "migrations are published but never auto-loaded, so persistence stays opt-in" — and the code contradicted it for three epics without anything noticing.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XXCNWQMB4C8NDZZF63G7AY', '01M2XXETZ6J6KCYTMCM78DZYV1', 'retro', '01M2X4NSDVG4E2B7EZJV63FE8Q', NULL, NULL, 4, 'Writing the README was the most effective design review of the run. Three questions only surfaced because someone had to be told the answer in plain words: does installing this bring migrations (it should not, and it did), do I need a database at all (the answer existed in ADR 01-08 and NFR3 but nowhere a reader would look), and what happens if I want persistence later (nobody had asked, and the failure was a raw SQL error).
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2XYDWW6BMFMDSV0X156S7MV', NULL, NULL, '01M2X3PAQTX6C4HAXY3BZ0KB2Q', NULL, NULL, 0, 'Chris''s critique of the delivered shape: `Result` was an object with an array of objects hanging off it, which smelled. It was also two behaviours for one mistake — `$result[''nope'']` threw a useful error while `$result->answers[''nope'']` returned null — and the two cases conditional questions create (an answer that did not apply, an answer too few samples qualified for) had no home, so `Recorder`, `EvalCommand` and the compat runner each hand-rolled their own null check.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2YY5QK08FEV6TV4DP1Y5X9H', '01M2Z039GH3H8TKT9WCHFQN59K', 'retro', '01M2YWZ0KYYPZ7QWRA1Y0V1A0J', NULL, NULL, 0, 'Changing a delivered behaviour cost far more in test churn than in source: nine lines of `Stopping` and one in the driver, against twenty existing tests across eight files that had encoded the old budget in their expected call counts. Sorting them needed a rule, and the rule that worked was to ask what each test''s subject was. A test about validity handling or token summing got `max_resamples: 0` pinned so it kept testing its one thing; a test whose subject actually was the budget was restated. One could be neither: `''ignores invalid samples when judging unanimity''` asserted that an adaptive run stops at three calls holding two valid samples, and no cap setting reaches that state any more, because `min` now means min valid. It was deleted rather than contorted, its claim folded into the replacement test, which still fails if an invalid sample is allowed to vote.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2YZP0KBFQ1VA43BMWZKV8N8', '01M2Z039GWCZVPR7ZVT71XJJVK', 'retro', '01M2YZ5VX91RKRVQ594V90Q756', NULL, NULL, 0, 'A schema-derived max-tokens ceiling of 136 tokens was silently costing accuracy for three epics, and the package''s own `#[MaxTokens(4096)]` attribute was dead the whole time because the SDK prefers a `maxTokens()` method over it. The invalid rate fell from 3.2% to 0.0% across 126 live samples when the formula was deleted.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M2YZPA5DV8H7Q1VD8JSBJ2W7', '01M2Z039GWCZVPR7ZVT71XJJVK', 'retro', '01M2YZ5VXNGCKFDGAR5WK3JR3F', NULL, NULL, 1, 'Writing the must-NOT for story 2 found a live privacy hole rather than confirming one was absent. `SampleValidator` named unexpected fields in the reason it produced — `Unexpected <key>.` — and a field name is the model''s to choose, so a model echoing state text as a key put that text into `hunch_samples.invalid_reason` and onto the `SampleInvalid` event. `Recorder` scrubs `reason` on the line above and writes `invalid_reason` untouched, so the column beside the protected one was the leak.
