INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2T9DGADRP9FDN336J240B', '01M2X2PQFR200HBQ1NACTB96MB', 1, 'Generate the package from the Spatie skeleton', 'Composer name `ninthspace/hunch`, root namespace `Ninthspace\Hunch\`, and the `php` `^8.3`, `illuminate/*` `^13.0` and `laravel/ai` constraints, with no `ext-*` requirements. Delete the skeleton''s `.github` workflows. Nothing is published.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2T9DZ2RDYKAAZN7CEVX7T', '01M2X2PQFR200HBQ1NACTB96MB', 2, 'Configure the test harness', 'Testbench base `TestCase`, Pest 4 with `tests/ArchTest.php`, SQLite in memory in `phpunit.xml`, and `Http::preventStrayRequests()` in the bootstrap. Addresses the harness criteria, not CI.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2T9E6YVBF6G71CQ5FHXCB', '01M2X2PQFR200HBQ1NACTB96MB', 3, 'Write tests for Scaffold ninthspace/hunch from the Spatie skeleton', 'Covers the criteria tagged unit or integration: the namespace architecture test and the composer.json assertions. The manual and target criteria are verified outside the suite.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2T9EAEAF945FV05SRSKZ1', '01M2X2PQG5VAKA5Z5DWBK7S489', 1, 'Add the composer test and test:offline scripts', '`composer test` runs Pest against Laravel 13 with no provider keys; `composer test:offline` runs it with outbound network denied at the OS level (macOS `sandbox-exec`), per the amended criterion 4. Addresses criteria 1, 3, 4 and 5.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2T9EJHPFHCYBQD890089X', '01M2X2PQG5VAKA5Z5DWBK7S489', 2, 'Add the composer check script', 'PHPStan with Larastan at level max and `pint --test`, exiting non-zero on any error. Addresses criterion 2 only.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2T9ER0P4XNE0STNJ54ND5', '01M2X2PQG5VAKA5Z5DWBK7S489', 3, 'Write tests for Run the checks locally through composer scripts', 'Covers the automated criteria: the outbound-request probe that must fail under `composer test:offline`, a check that no default-suite test skips on a missing key or network, and an architecture test that no `.github/workflows` exists.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2ZJ4YQWQCQ3T7KQRWMP06', '01M2X2WD2SWE7Q68HE1ZT85C5R', 1, 'Implement the three question types with their validation', 'Option-count bounds from `hunch.choice.max_options`, option-key rules, Boolean description keys, Score level order and minimum. Construction and validation only; no prompt rendering.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2ZJ5CRBZQB8JGBR3F7EME', '01M2X2WD2SWE7Q68HE1ZT85C5R', 2, 'Write tests for Define the Boolean, Choice and Score question types', 'Covers the six unit-tagged criteria.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2ZJ5MY8V98V1YF82WGZK8', '01M2X2WD35666W5YFGX0AC9NCR', 1, 'Serialise a question set to versioned canonical JSON', 'Question keys sorted, option and level order kept, prompt options included, version name and state excluded, per ADR 01-11. The serialisation only, not the hash.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2ZJ5XTRY6JM4V5ZMQ5ME3', '01M2X2WD35666W5YFGX0AC9NCR', 2, 'Compute the prefixed sha256 question set hash', 'The identity and its format-version prefix, with the version name carried alongside and never hashed. Storage belongs to the persistence epic.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2ZJ63QMNT0CMR6J8RXR96', '01M2X2WD35666W5YFGX0AC9NCR', 3, 'Write tests for Hash a question set''s content', 'Covers the six unit-tagged criteria, including the golden fixture and the separate-process determinism check.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2ZJ6AMW69NMB0EBG8YAK4', '01M2X2WD3CYT5VNQDT21WQGYRM', 1, 'Derive per-sample seeds and shuffle with Randomizer and Xoshiro256**', 'Seed from the classification ULID and sample number, per ADR 01-09, without touching the global RNG. Produces permutations; rendering them is the prompt story''s.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2ZJ6JQ9H4NCG6TXVAWK29', '01M2X2WD3CYT5VNQDT21WQGYRM', 2, 'Write tests for Seed each sample''s shuffles', 'Covers the three unit-tagged criteria, including the golden fixture run under `composer test` and the global-RNG check.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2ZJ6QVRHZ4JFJE36TN3F4', '01M2X2WD3H50F7E9Z22QJQ1618', 1, 'Render the instructions', 'Role with the do-not-follow line, application context, questions and descriptions under stable IDs, how to answer each type, and the prompt options. Nothing that varies per run.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2ZJ6ZRFWQHFZ175DFENDZ', '01M2X2WD3H50F7E9Z22QJQ1618', 2, 'Render the per-sample user message', 'Shuffled orders and the state inside `<state>` tags, named sections for array state, closing tag neutralised. Carries no question text, descriptions or context.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2ZJ75P37WRD86GDP3J857', '01M2X2WD3H50F7E9Z22QJQ1618', 3, 'Generate the canonical schema', 'One required field per question; enums of canonical keys in declared order regardless of shuffle. Validation of responses belongs to the pipeline epic.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X2ZJ7CZTZ0EPFYGMK8HAE8', '01M2X2WD3H50F7E9Z22QJQ1618', 4, 'Write tests for Build the split prompt: instructions, user message and schema', 'Covers the ten unit- and integration-tagged criteria.', 'complete', NULL, 4);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3K112KMEK0QC734M3PASS', '01M2X3F42MDK6E4K99JM5N3G7V', 1, 'Write tests for Aggregate valid votes into shares', 'Test-first: covers the six unit-tagged criteria and fails until the aggregator exists.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3K11SDQXP5JQBD32Q0VC5', '01M2X3F42MDK6E4K99JM5N3G7V', 2, 'Implement aggregation for Boolean, Choice and Score over valid samples', 'Shares, choice, confidence, entropy, mean score and nearest level. Pure with no I/O; invalid samples excluded. Tie resolution is the next story''s.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3K1240FYGFCPZ11VSE74S', '01M2X3F4386SRTE9GGQV8Q97MJ', 1, 'Write tests for Resolve ties between leading answers', 'Test-first: covers the five unit-tagged criteria.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3K12C8Q45Q791RZH679HT', '01M2X3F4386SRTE9GGQV8Q97MJ', 2, 'Implement tie resolution with tieBreak and canonical order', 'A `tieBreak` value among the tied answers wins, otherwise the earliest in canonical order; sets `tied`. Choice and Score only; Booleans are untouched.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3K12JA61AA9DJ8G6X7F38', '01M2X3F43JWE81PW25VTPEHQNV', 1, 'Implement immutable BooleanAnswer, ChoiceAnswer and ScoreAnswer', 'SDK-shaped properties plus Hunch''s additions, and `bucket` from the configured buckets. `applies` defaults to true until conditional questions land; `calibration()` returns null until persistence lands.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3K12TB5R9XPJM93WPHQ5S', '01M2X3F43JWE81PW25VTPEHQNV', 2, 'Write the honesty docblocks and the README "Probabilities are estimates" section', 'Addresses the docblock and README criteria only: vote-share estimates, not calibrated probabilities, pointing to `calibration()`.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3K133YVGSR767XP5JT39W', '01M2X3F43JWE81PW25VTPEHQNV', 3, 'Write tests for Expose SDK-shaped answer objects', 'Covers the six unit-tagged criteria, including the docblock architecture test. The README criteria are manual.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4R5DX5XVZ89M74J239X', '01M2X3PAQ600X4YN32S2379EJG', 1, 'Write config/hunch.php and register publishing', 'Every FR16 key with its default, published under the `hunch-config` tag. Migrations are loaded only when persistence is on.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4RWTDGFSN083MQQKYZW', '01M2X3PAQ600X4YN32S2379EJG', 2, 'Parse and validate the sampling rule and persistence settings', '`fixed:N` and `adaptive:MIN-MAX` parsing with malformed values rejected on first use; persistence without `retention_days` rejected at boot.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4S45DACTTESHYRFEQF5', '01M2X3PAQ600X4YN32S2379EJG', 3, 'Write tests for Publish and read the configuration', 'Covers the four unit- and integration-tagged criteria.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4SCX2V4TPVZD3J98FRN', '01M2X3PAQK8SA1R4N8CQV8W9X3', 1, 'Define the ClassificationDriver contract and resolve the driver from the provider', '`classify(State, QuestionSet, Options): Result` per ADR 01-02; any provider other than `typesafe` resolves the sampling driver. TypeSafe resolution itself belongs to the TypeSafe epic.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4SM4FB75QPSCGTB71CQ', '01M2X3PAQK8SA1R4N8CQV8W9X3', 2, 'Implement the fluent builder with its pre-call checks', '`of`, `context`, `question(s)`, `using`, `sampling`, `timeout`, `classify`; builder values override config. Rejects a missing provider, an empty question set and a non-positive sample count before any model call.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4SXYN3ECZTC4D74BD4B', '01M2X3PAQK8SA1R4N8CQV8W9X3', 3, 'Implement ClassifierAgent', '`Agent` + `HasStructuredOutput` with Temperature 1.0, schema-sized MaxTokens, CacheInstructions and no TopP; not conversational; class replaceable through `hunch.agent`.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4T3CFA36SGYCT4SW0SV', '01M2X3PAQK8SA1R4N8CQV8W9X3', 4, 'Implement SamplingDriver fixed sampling', 'N sequential prompts with provider, model and timeout, each using the split prompt and seeded shuffles, feeding the aggregator. The happy path only; validation, retries and the full Result are later stories.', 'complete', NULL, 4);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4TB76ZYBVGE0KA0SE56', '01M2X3PAQK8SA1R4N8CQV8W9X3', 5, 'Write tests for Classify through the sampling driver with fixed sampling', 'Covers the fourteen unit-, integration- and feature-tagged criteria.', 'complete', NULL, 5);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4TKGQXA00K1RFJQ2XX2', '01M2X3PAQTX6C4HAXY3BZ0KB2Q', 1, 'Implement Result', 'Read-only `ArrayAccess` by question key, sample counts, summed usage including cache reads and writes, `meta` with seeds and request IDs, and the classification ULID `id`. `reasons` stays null until reasons land.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4TTZ9PP2ZKX83JJQCQN', '01M2X3PAQTX6C4HAXY3BZ0KB2Q', 2, 'Write tests for Report the Result', 'Covers the seven unit- and integration-tagged criteria.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4V17XYXNETX5P546ZWF', '01M2X3PAR1J7H3S0E8M2HK6PT1', 1, 'Validate each sample against the schema', 'Missing fields, extra fields, non-canonical enum values and free text mark a sample invalid; invalid samples are recorded and excluded from every vote.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4V79W886Q105JC3VQ7V', '01M2X3PAR1J7H3S0E8M2HK6PT1', 2, 'Throw ClassificationFailed with partial samples and usage', 'Too few valid samples or a persistent provider error throws, never a defaulted answer. `min_valid_samples` is checked against the rule''s fewest samples before any call and never scaled.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4VF2893KKKABM63ZF7A', '01M2X3PAR1J7H3S0E8M2HK6PT1', 3, 'Write tests for Validate samples and fail loudly', 'Covers the eight unit- and integration-tagged criteria.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4VP7Y73XNE1166W5F33', '01M2X3PAR7KMGX8S8MEGDQMJ81', 1, 'Retry rate-limit and overload errors against the same provider', 'Backoff through `Sleep`, up to `retries`; non-retryable errors fail at once; SDK failover passed through only when `failover` is true.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4VXZCZBKM2W63TFDTYV', '01M2X3PAR7KMGX8S8MEGDQMJ81', 2, 'Write tests for Retry rate limits against the same provider', 'Covers the five integration-tagged criteria.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4W5N84M8Z287YT5E909', '01M2X3PARECS7ZV29Y9AWRP4YE', 1, 'Implement Hunch::fake with direct answers and scripted samples', 'Direct answers skip the agent; scripted samples run the real aggregator; seeds are fixed so user messages are deterministic. Returns the same answer classes as the sampling driver.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4WBQHH6JN0KQV0N9551', '01M2X3PARECS7ZV29Y9AWRP4YE', 2, 'Implement the fake''s assertions and preventStrayClassifications', '`assertClassified` with readable failures, `assertSampledTimes`, and throwing on unmatched classifications when stray prevention is on.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4WJ2FF68CPSDVV0Z27X', '01M2X3PARECS7ZV29Y9AWRP4YE', 3, 'Write tests for Provide testing fakes', 'Covers the eight feature- and integration-tagged criteria, including the sampling-versus-fake driver contract test.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4WRRVG755FTQVQDEZY8', '01M2X3PARMWT80YW93RZ4WMB55', 1, 'Write the cross-story integration tests for the sampling pipeline', 'End to end through `ClassifierAgent::fake()`, identical instructions across classifications, zero queries with persistence off, and a missing database driver. Spans config, driver, Result and fakes; no new production code.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4WZ86DDJZM44TDRGHPH', '01M2X3PARWSK1WDC47BZ075G0C', 1, 'Document the host smoke-check procedure', 'How to run the four target checks on a production host: SDK version, no queue worker, no database, local-model-only network. Verification happens on the host, not here.', 'withdrawn', 'Pivot on spec 01: Hunch is a package with no production host, so there is no host smoke-check procedure to document. The runtime checks run in the package suite.', 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X3Y4X7DHJYXB2S7PC67Y52', '01M2X3PARWSK1WDC47BZ075G0C', 2, 'Write tests for the runtime requirements', 'Covers all four criteria: the SDK-fake smoke `classify()`, `classify()` with no database, synchronous `classify()`, and the HTTP-client architecture test.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490C0WY45QGXYKNMS5ZRV', '01M2X43NBV9QJZG03JQPXE2RX6', 1, 'Write tests for Sample adaptively', 'Test-first: covers the six unit-tagged criteria and fails until the stopping rule exists.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490C9QKWWXWBB5SMEM50A', '01M2X43NBV9QJZG03JQPXE2RX6', 2, 'Implement the adaptive stopping rule', 'Take `min`, then add 2 at a time capped at `max`; stop on unanimity or when the leader cannot be overtaken or tied. Invalid samples are excluded from unanimity but count toward `max`.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490CQGGWKQ6SW99V85NPJ', '01M2X43NC67JZ2MN60EJX8C7S8', 1, 'Write tests for Ask conditional questions', 'Test-first: covers the six unit-tagged criteria.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490D024G336HRQD4JRJZN', '01M2X43NC67JZ2MN60EJX8C7S8', 2, 'Implement onlyWhen conditional questions', 'Build-time validation of the controlling key and values; aggregation over qualifying samples only; `applies` from the winning controlling answer; null under 2 qualifying samples; non-applying questions left out of adaptive unanimity.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490D6QVNDBPZRZ0SSFHT7', '01M2X43NCDZTGS6DSCP2X35JBT', 1, 'Implement withReasons', 'Schema `reason` field, an instruction line with the character limit, truncation that keeps the sample valid, and `Result->reasons`. Reasons are display-only and never read back into anything.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490DEE7RP42JFFD5GGZ46', '01M2X43NCDZTGS6DSCP2X35JBT', 2, 'Write tests for Ask for short reasons', 'Covers the five unit- and integration-tagged criteria, including the architecture test on reason reads.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490DMQG1PRRDW7BW02MMB', '01M2X43NCK5QP7BJGJE7E83V4K', 1, 'Implement redactUsing', 'Runs once per classification before the first model call, per named part for array state, and `state_hash` is sha256 of the redacted rendered state. The persisted-row check belongs to the persistence epic.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490DTS1ZKSV3PC96N2TBT', '01M2X43NCK5QP7BJGJE7E83V4K', 2, 'Write tests for Redact the state before sampling', 'Covers the four unit- and integration-tagged criteria.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490E1N3GFVMR7YBNXA203', '01M2X43NCTAD4C4MEFDH15FR4J', 1, 'Implement the ContactDetails redactor and its fixture', 'Emails to `[email]` and phone numbers to `[phone]`, with a 20-string labelled fixture of positives and negatives. Off unless explicitly set.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490E8TG6EGN59WFMV3JMJ', '01M2X43NCTAD4C4MEFDH15FR4J', 2, 'Write tests for Provide the contact-details redactor', 'Covers the four unit- and integration-tagged criteria.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490EEDBWGFHBZRE5BCTKA', '01M2X43ND0Y6N6614NQ2664K8Z', 1, 'Define and dispatch the classification events', '`Classifying`, `SampleTaken`, `SampleInvalid`, `Classified` and `ClassificationFailed`, with payloads of IDs, hashes and counts, never the state. `Labelled` and `CalibrationComputed` belong to the persistence epic.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X490EN3G45TE01TAYJV6HF', '01M2X43ND0Y6N6614NQ2664K8Z', 2, 'Write tests for Dispatch classification events', 'Covers the five unit- and integration-tagged criteria.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4DGXNEZD7QW6DX776NB', '01M2X4BCM6K3E8X01P5XYSD8HK', 1, 'Write migrations and models for the five Hunch tables', '`hunch_question_sets`, `hunch_classifications`, `hunch_samples` (with `reason` and `band`), `hunch_labels` (with `superseded_at`) and `hunch_calibration` keyed by the full cell. `state_hash` only, never the state.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4E9VMA67FFKRKCM5GNP', '01M2X4BCM6K3E8X01P5XYSD8HK', 2, 'Implement record() persistence', 'Classification with subject morph and `state_hash`, one sample row per sample, question set row if new, reasons only when requested, failed runs with the state scrubbed from `error`. Throws when persistence is off.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4EKT004XT6G797DMX40', '01M2X4BCM6K3E8X01P5XYSD8HK', 3, 'Implement pruning with Prunable, sparing labels', 'Classifications older than `retention_days` go with their samples; labels and classifications with a current label are never pruned.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4EWXA55H6WTK2DW72C1', '01M2X4BCM6K3E8X01P5XYSD8HK', 4, 'Write tests for Persist classifications without the state', 'Covers the eleven unit- and integration-tagged criteria, including the marker scans across rows, logs and cache, and the redaction check on persisted rows.', 'complete', NULL, 4);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4F4459YDSNTVVFNV0G5', '01M2X4BCMTDY477RCHQHRDDJCH', 1, 'Implement Hunch::label', 'Validates the classification ID, question keys and canonical values before writing; supersedes the earlier label for the same question without deleting it; dispatches `Labelled`.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4FDH9R3ZSHEGPS75CZV', '01M2X4BCMTDY477RCHQHRDDJCH', 2, 'Write tests for Record human labels', 'Covers the four integration-tagged criteria.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4FNZJDGWDYKJTSE3EW9', '01M2X4BCN25081Q59KW35SEYAS', 1, 'Write tests for Compute calibration with hunch:calibrate', 'Test-first: covers the three unit-tagged statistics criteria and the six integration-tagged command criteria against a seeded SQLite fixture.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4FX9P7DPNQM8WRFNBR4', '01M2X4BCN25081Q59KW35SEYAS', 2, 'Implement the Wilson lower bound, Brier score and ECE', 'Pure functions shared by `hunch:calibrate` and `hunch:eval`; multi-class Brier for Choice.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4G5605D12M97BS8KQ61', '01M2X4BCN25081Q59KW35SEYAS', 3, 'Implement the hunch:calibrate command', 'Per-cell rows from current labels only, per-question Brier, ECE and reliability table, cells never merged across drivers or models, idempotent replacement, and one `CalibrationComputed` per run.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4GD6Y2CE9C28DF3J2SX', '01M2X4BCNA0ZTGJGBTXDJ9EGHR', 1, 'Validate buckets and implement the calibration() lookup', 'Strictly descending edges in (0, 1]; lookup by the exact cell, gated by `calibration.min_n`; null with no query when persistence is off.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4GMNN3BAXSCTYKWT9NC', '01M2X4BCNA0ZTGJGBTXDJ9EGHR', 2, 'Write tests for Read calibration back through buckets', 'Covers the six unit- and integration-tagged criteria.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4GV62E451KYZCEP0DF9', '01M2X4BCNHT6RWZV3RH04GZCMC', 1, 'Implement the hunch:eval command', 'Parses `driver:provider:model` before any call, re-classifies the labelled items per driver, reuses the calibrate functions, reports token usage but no cost, and writes nothing `hunch:calibrate` would count.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4H3RE4KEB3VZ5WT5E9Z', '01M2X4BCNHT6RWZV3RH04GZCMC', 2, 'Write tests for Compare drivers with hunch:eval', 'Covers the five feature-, integration- and unit-tagged criteria.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4HAEWW8CWS8SAGE9AN1', '01M2X4BCNRCV1FX6Y4R6KM0JJD', 1, 'Implement withSelfReport bands', 'Band schema field and instruction set, bands recorded per sample, and per-band accuracy, Brier and ECE in `hunch:calibrate`. Bands never affect votes, probabilities, buckets or answers.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4HK967PPPJGECBD5JCC', '01M2X4BCNRCV1FX6Y4R6KM0JJD', 2, 'Write tests for Record self-reported confidence bands', 'Covers the four unit- and integration-tagged criteria.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4K4HV5Y0XJQTFNFRF2RB7', '01M2X4BCNZM3CXM6YEPA71KFGR', 1, 'Write the cross-story integration tests for persistence and calibration', 'From `record()` through `Hunch::label()` and `hunch:calibrate` to `calibration()`, and relabel-then-recalibrate. No new production code.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4RH87WHTQS1ESQ3XJZGWP', '01M2X4NSD4BZMPQ2ZCDXBYBQKE', 1, 'Build the synthetic labelled compatibility fixture set', 'Under `tests/Fixtures/compat/`: no real personal data, every item labelled unambiguously, and three groups totalling 42 items — 24 core (Boolean, small Choice and Score in one set), 12 for the 40–50 option Choice, and 6 injection items whose state asks for a fixed option. See the epic''s "Fixture set size" section for why.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4RH8SXB5SCKR32XCC973A', '01M2X4NSD4BZMPQ2ZCDXBYBQKE', 2, 'Write the compatibility suite', 'Runs against Anthropic at `fixed:3` per item, so a run is 126 samples: schema-invalid rate threshold of 10% (which trips at 13 of 126), aggregation and full `meta` checks, the cache-read check on the large-Choice group, and reported-not-failed injection compliance and large-Choice results. Lives outside the default suite.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4RH947T18X12H23440YJ1', '01M2X4NSD4BZMPQ2ZCDXBYBQKE', 3, 'Add the composer compat script', 'Manual and local only: reads `ANTHROPIC_API_KEY` from the environment, exits non-zero with a clear message when it is absent, and never stores a key in the repository.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4RH9FJZ65H838M3433SXX', '01M2X4NSD4BZMPQ2ZCDXBYBQKE', 4, 'Write tests for Run the compatibility command locally against Anthropic', 'Covers the unit-tagged fixture labelling check and tests of `composer compat`''s key source and absent-key exit; the integration criteria are verified by a completed manual run.', 'complete', NULL, 4);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4RHA07XXAWASJ3HK9JWHC', '01M2X4NSDVG4E2B7EZJV63FE8Q', 1, 'Write the results table into the README locally', 'Accuracy and token usage per provider written into the README results table and nothing else; no commit, push or pull request.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4RHACB57KVXHWHSH3TZBT', '01M2X4NSDVG4E2B7EZJV63FE8Q', 2, 'Write tests for Write provider results to the README locally', 'Covers the table writer changing only the results section of `README.md`.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4Y8K7MFM69SJ1F10DSFWW', '01M2X4S6Z75HDJ79E2NMVJPBVS', 1, 'Implement TypeSafeDriver over the SDK''s Classification', 'Delegates to `Classification` and maps results onto Hunch''s answer classes: conditional questions asked unconditionally with `applies` from the controlling Choice, no reasons (recorded in `meta`), top-share confidence with any native value in `meta`.', 'pending', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4Y8KQY4D36AW3SX74CQY9', '01M2X4S6Z75HDJ79E2NMVJPBVS', 2, 'Resolve typesafe to the TypeSafe driver and keep its cells and key separate', '`using(''typesafe'')` resolves this driver; calibration cells are keyed by driver; the API key never reaches `meta`, events, exceptions or persisted rows.', 'pending', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4Y8M0CBVCWA68659R35QB', '01M2X4S6Z75HDJ79E2NMVJPBVS', 3, 'Write tests for Classify through TypeSafe', 'Covers the seven unit- and integration-tagged criteria, including the driver contract test against the sampling driver.', 'pending', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4Y8M9E8X8P2ZCPYJWX1DF', '01M2X4S6ZFPVH8E9P1Z7NB4TSH', 1, 'Add TypeSafe to composer compat, gated on its key', 'Runs the fixture set through TypeSafe when `TYPESAFE_API_KEY` is set in the local environment, and skips with a visible notice when it is absent.', 'pending', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2X4Y8MGEZZS9DMF8EJ65Z3M', '01M2X4S6ZFPVH8E9P1Z7NB4TSH', 2, 'Write tests for Add TypeSafe to the compatibility run', 'Covers the integration-tagged criterion through a test that TypeSafe runs only when `TYPESAFE_API_KEY` is set and otherwise prints the skip notice.', 'pending', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2YX1GA2ZVTBX4M89S3A3J3F', '01M2YWZ0KYYPZ7QWRA1Y0V1A0J', 1, 'Add `max_resamples` to the config and Settings', 'Publish `max_resamples` in `config/hunch.php` with a default of 2 and a comment saying what 0 means, and read it through `Settings::int` clamped at 0 so a negative value cannot shrink the rule. Serves criterion 5.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2YX1GAJ91ZM40VRRFCWAAEJ', '01M2YWZ0KYYPZ7QWRA1Y0V1A0J', 2, 'Count valid samples in Stopping, bounded by the call ceiling', '`nextBatch()` takes the resampling allowance and works from two counts: the valid samples so far, which the rule''s min and max are measured against, and the calls spent, which the ceiling of `rule max + allowance` bounds. The samples still to come is the smaller of the two headrooms, and that figure is what the adaptive settle check is given, so the cap can settle a run the rule alone would continue. Serves criteria 1, 2, 3 and 4.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2YX1GAWVEFPZ5QE2F2FR9PT', '01M2YWZ0KYYPZ7QWRA1Y0V1A0J', 3, 'Pass the allowance through the sampling driver', '`SamplingDriver` reads the allowance once per classification and passes it to each `nextBatch()` call. Sample numbering, seeds, events, aggregation and the `min_valid_samples` check are left exactly as they are — numbering already increments per call, which is what keeps a replacement''s seed its own. Serves criteria 6 and 7.', 'complete', 'The clamp on a negative allowance ended up in Stopping rather than the driver, where the default argument needs it anyway; the driver passes the setting through unchanged.', 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2YX1GB5V9YV01076VSTQXA6', '01M2YWZ0KYYPZ7QWRA1Y0V1A0J', 4, 'Tests, each shown failing against a confirmed plant', '`tests/Sampling/ResamplingTest.php` covers the seven criteria: a fixed top-up, an adaptive top-up that does not settle short, the cap and its `ClassificationFailed`, `max_resamples: 0`, the config key, distinct seeds and numbers, and aggregation unchanged with the invalid samples still recorded and still dispatching `SampleInvalid`. Each must-NOT carries a control that would catch the rejected thing. Every test is shown failing against a planted defect, and each plant is confirmed to have applied.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2YX1GBGYXV7HBRTC3J1ZAM9', '01M2YWZ0KYYPZ7QWRA1Y0V1A0J', 5, 'Document the replacement in the README', 'Add `max_resamples` to the configuration reference table and rewrite "Sampling, and what happens when it fails" so it says an invalid sample is replaced, what the cap costs at worst, and that 0 turns replacement off. Serves criterion 5.', 'complete', NULL, 4);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2YZNDS601HRPE8MDR0C6Y3Z', '01M2YZ5VX91RKRVQ594V90Q756', 1, 'Delete the computed ceiling and let the attribute stand', 'Remove `ClassifierAgent::maxTokens()`, leaving `#[MaxTokens(4096)]` as what the SDK resolves, and say in the class docblock why a tight ceiling is not worth having. Replace the test that asserted the formula with one asserting the ceiling is the attribute''s whatever the question set, and one showing the largest answer the schema allows is an order of magnitude below it.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2YZNDSP4R77CHTWWJSVERXS', '01M2YZ5VXNGCKFDGAR5WK3JR3F', 1, 'Distinguish an answer that never arrived from a bad one', '`SampleValidator` reports an output carrying none of the expected keys as having no structured data, or as answering none of the questions when it carries keys of its own, rather than listing every field as missing.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2YZNDT2BHC77BKP77EEGPAE', '01M2YZ5VXNGCKFDGAR5WK3JR3F', 2, 'Count unexpected fields rather than naming them', 'A field name is the model''s to choose and can quote the state, and `invalid_reason` is written to the sample row unscrubbed and carried on `SampleInvalid` — unlike `reason`, which the recorder scrubs. Report the count instead, and prove it with a fake that names a field after a marker in the state.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M2YZNDTE62HY2PGNHQ6MA64D', '01M2YZ5VXNGCKFDGAR5WK3JR3F', 3, 'Record the provider''s stop reason in the compatibility run', 'Read `stop_reason` from the raw response on `AgentPrompted`, pair it with its sample by order, and print it beside each invalid reason, so a truncated answer reads as truncation.', 'complete', NULL, 2);
