INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M2X2T9F6S1N4RX0FQJMKBJ9N', '01M2WZ4G4BXTQP2Q7EWS5JPM1G', 'Nothing is published (no Packagist submission, no public repository, no tagged release) until ownership of the code is confirmed.', '01M2X2QF03V15M58NPZGN9BG7R', 2, NULL, NULL, '2026-09-20T09:57:59.273Z', 'The clause it quoted was removed from NFR8 on 2026-09-20. The release gate was a mistake in the original spec: authorship and origin of the code were never in question, so there was nothing for publication to wait on.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M2X2T9FB2ZETA4ZAH4QWKR9X', '01M2WVS5PRMF1MB0AT2AM7T7AW', 'the host runs PHP 8.3 or later.', '01M2X2QF0PTGKXD8KH674KA1VR', 3, NULL, NULL, '2026-09-19T18:10:45.830Z', 'ENV1 amended (pivot 2026-09-19): "the host runs PHP 8.3 or later." removed; Hunch is a package with no host. Rebound to the composer.json constraint clause.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M2X2T9FHPVYFT0WJBJ83TXV2', '01M2WVS5PRMF1MB0AT2AM7T7AW', 'the host runs PHP 8.3 or later.', '01M2X2QF0W6BSJHE2F62KZDRCE', 4, NULL, NULL, '2026-09-19T17:50:00Z', 'The criterion this bound was superseded: Hunch is a package with no production host. Composer enforces `php` `^8.3` in any installing app, and criterion 3''s composer.json test covers it.');
