INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M2X2T9G13M8P9GSPVP9D6GQ5', '01M2WVS5QT7D8V4JMT9YMX9WWE', 'the host has a `laravel/ai` version', '01M2X2QF1FX3HX4YQ6089Z3XA9', 7, NULL, NULL, '2026-09-19T18:10:45.846Z', 'ENV3 amended (pivot 2026-09-19): "the host has" removed; Hunch is a package with no host. Rebound to "Hunch requires a `laravel/ai` version".');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M2X2T9G6H9134P22S5KBWS9E', '01M2WVS5RDV2J4H2DWHNZYC7FX', 'Its composer.json declares no additional `ext-*` requirements.', '01M2X2QF1MSNKZX102H9N9VSE3', 8, '2026-09-19T19:25:00Z', 'ff44aff292a6334ab7cfb3f68c4375d5b08c168126cc8c041efeb73329531809', NULL, NULL);
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M2X2T9GD55AJEWGJJ9DD45WQ', '01M2WVS5RDV2J4H2DWHNZYC7FX', 'Hunch must not require any PHP extension beyond those Laravel itself requires.', '01M2X2QF1VV3V4KKXG2CAEAHSP', 9, NULL, NULL, '2026-09-19T17:50:00Z', 'The criterion this bound was superseded: Hunch is a package with no production host. It declares no `ext-*` requirement of its own, so it adds nothing to an installing app''s platform check; criterion 8''s composer.json test covers it.');
