INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M2X2T9HFBXZ1KKGZCFVEFGS3', '01M2WVS5SD8R6JZ2NYXXZDCM99', 'CI runs PHPStan with Larastan at level max, and `pint --test`, and fails on any error.', '01M2X2QF2YK917G2DKK2A14693', 15, NULL, NULL, '2026-09-19T15:48:19.640Z', 'ENV8 amended: PHPStan and Pint run locally via `composer check`, not in CI.');
